INSERT INTO error_codes (code, title, category, description, common_causes, fix_steps, severity) VALUES
('CRITICAL_PROCESS_DIED', 'Critical Process Died (BSOD)', 'bsod', 'A critical system process stopped unexpectedly. Windows cannot continue running.', 'Corrupted system files, failing RAM, driver conflicts, Windows update issues, malware.', '1. Run sfc /scannow as admin. 2. Run DISM /Online /Cleanup-Image /RestoreHealth. 3. Check RAM with Windows Memory Diagnostic. 4. Update all drivers via Device Manager. 5. If persistent, check event viewer for failing process.', 'critical'),
('KERNEL_DATA_INPAGE_ERROR', 'Kernel Data Inpage Error (BSOD)', 'bsod', 'Windows failed to read/write kernel data from the page file. Usually disk or RAM failure.', 'Failing hard drive, bad sectors, corrupted page file, failing RAM, loose SATA cable.', '1. Run chkdsk C: /f /r. 2. Test RAM with MemTest86 overnight. 3. Check SMART with CrystalDiskInfo. 4. Reseat SATA/NVMe cable. 5. Replace drive if errors found.', 'critical'),
('IRQL_NOT_LESS_OR_EQUAL', 'IRQL Not Less or Equal (BSOD)', 'bsod', 'A driver or process tried to access memory at an unauthorized kernel address.', 'Faulty driver (network, GPU, audio), overclocking, failing RAM, malware.', '1. Boot Safe Mode. 2. Uninstall recent drivers. 3. Run Driver Verifier. 4. Reset overclock. 5. Run memtest86.', 'critical'),
('PAGE_FAULT_IN_NONPAGED_AREA', 'Page Fault in Nonpaged Area (BSOD)', 'bsod', 'Windows requested data from memory not available in the nonpaged area.', 'Failing RAM, corrupted page file, driver issues, disk errors.', '1. Run chkdsk C: /f /r. 2. Windows Memory Diagnostic. 3. MemTest86. 4. Recreate page file. 5. Check RAM sticks.', 'critical'),
('SYSTEM_SERVICE_EXCEPTION', 'System Service Exception (BSOD)', 'bsod', 'A system service encountered an unhandled exception.', 'Outdated GPU drivers, Windows update conflicts, antivirus, malware.', '1. Update GPU drivers. 2. Uninstall third-party antivirus. 3. Run sfc /scannow. 4. Check update history. 5. System restore.', 'critical'),
('DPC_WATCHDOG_VIOLATION', 'DPC Watchdog Violation (BSOD)', 'bsod', 'A Deferred Procedure Call took too long, triggering the watchdog timer.', 'SSD firmware issues, outdated storage drivers, loose cables, USB conflicts.', '1. Update SSD firmware. 2. Update Intel RST/AMD RAID drivers. 3. Check cables. 4. Remove USB devices. 5. Check SSD health.', 'critical'),
('WHEA_UNCORRECTABLE_ERROR', 'WHEA Uncorrectable Error (BSOD)', 'bsod', 'Hardware error reported by Windows Hardware Error Architecture.', 'CPU overheating, failing motherboard, overclocking, GPU failure, PSU issues.', '1. Reset BIOS to default. 2. Check temps. 3. Reseat GPU/RAM. 4. Test PSU. 5. May need hardware replacement.', 'critical'),
('KERNEL_SECURITY_CHECK_FAILURE', 'Kernel Security Check Failure (BSOD)', 'bsod', 'A kernel-mode process or driver failed a security check.', 'Incompatible drivers, corrupted system files, memory issues, antivirus conflicts.', '1. Boot Safe Mode. 2. Update all drivers. 3. Uninstall incompatible software. 4. Run sfc and DISM. 5. System restore.', 'critical'),
('INACCESSIBLE_BOOT_DEVICE', 'Inaccessible Boot Device (BSOD)', 'bsod', 'Windows cannot access the system partition during boot.', 'SATA mode changed, driver issues, corrupted boot sector, disk failure.', '1. Check BIOS SATA mode (AHCI). 2. Boot recovery USB. 3. bootrec /rebuildbcd. 4. bootrec /fixmbr. 5. Check disk health.', 'critical'),
('MACHINE_CHECK_EXCEPTION', 'Machine Check Exception (BSOD)', 'bsod', 'Hardware reported a fatal unrecoverable error.', 'CPU failure, overheating, failing motherboard, bad RAM, overclocking.', '1. Stop overclocking. 2. Check CPU cooler. 3. MemTest86. 4. Check motherboard caps. 5. Minimal hardware test.', 'critical'),
('0x80070002', 'Windows Update Error 0x80070002', 'update', 'Windows Update cannot find specified files. Files may be corrupted.', 'Corrupted SoftwareDistribution, wrong date/time, system file corruption.', '1. Run Update Troubleshooter. 2. Delete SoftwareDistribution folder. 3. Set correct date/time. 4. Disable antivirus. 5. sfc /scannow.', 'medium'),
('0x80070005', 'Update Error 0x80070005 Access Denied', 'update', 'Windows Update encountered access denied error.', 'Antivirus blocking, Group Policy, corrupted files, Installer service issue.', '1. Run Troubleshooter as admin. 2. Reset Update components. 3. Check Group Policy. 4. DISM restore. 5. Rename catroot2.', 'medium'),
('0x800f0922', 'Update Error 0x800f0922', 'update', 'Windows Update server timed out or unreachable.', 'VPN active, firewall blocking, low disk space, Update service stopped.', '1. Disconnect VPN. 2. Disable firewall. 3. Free 2GB space. 4. Restart Update service. 5. Try from Settings.', 'medium'),
('0x80004005', 'Windows Error 0x80004005', 'windows', 'Generic unspecified Windows error in many contexts.', 'Corrupted system files, permissions, antivirus interference, registry corruption.', '1. sfc /scannow. 2. DISM restore. 3. Check Event Viewer. 4. Delete temp files. 5. Try in Safe Mode.', 'medium'),
('0xc000021a', 'Critical System Error 0xc000021a', 'windows', 'Critical Windows system process failed. Cannot boot normally.', 'Corrupted files, failed update, driver conflict, malware, registry corruption.', '1. Recovery Mode. 2. sfc /scannow /offbootdir. 3. DISM image. 4. System Restore. 5. Reset PC.', 'critical'),
('0x80300024', 'Install Error 0x80300024', 'windows', 'Windows cannot install to selected disk.', 'Wrong GPT/MBR, wrong boot mode, missing driver, disk locked.', '1. Check BIOS boot mode. 2. Delete all partitions. 3. Load storage drivers. 4. Different USB port. 5. diskpart clean.', 'high'),
('ERR_CONNECTION_REFUSED', 'Connection Refused', 'network', 'Browser cannot connect to server. Connection actively refused.', 'Server not running, firewall blocking, wrong URL, DNS wrong IP.', '1. Verify URL. 2. Check server running. 3. Ping server IP. 4. Check firewall. 5. Try different device.', 'medium'),
('ERR_NAME_NOT_RESOLVED', 'DNS Name Not Resolved', 'network', 'Browser cannot resolve domain name to IP.', 'DNS down, cache corrupted, no internet, domain expired, hosts override.', '1. ipconfig /flushdns. 2. Change DNS to 8.8.8.8. 3. Ping 8.8.8.8. 4. Ping google.com. 5. Check hosts file.', 'medium'),
('ERR_TIMED_OUT', 'Connection Timed Out', 'network', 'Connection took too long and was abandoned.', 'Slow internet, server overloaded, firewall dropping packets, proxy issues.', '1. Speed test. 2. Check other sites. 3. Flush DNS. 4. Disable proxy. 5. Check firewall. 6. Contact ISP.', 'medium'),
('DNS_PROBE_FINISHED_NO_INTERNET', 'DNS Probe No Internet', 'network', 'Chrome detected no internet. DNS lookup failed.', 'Adapter disabled, cable disconnected, router issue, ISP outage, IP problem.', '1. Check cable. 2. Restart router. 3. ipconfig release/renew. 4. netsh winsock reset. 5. Restart PC.', 'high'),
('SMART_HARD_DISK_ERROR', 'SMART Hard Disk Error', 'hardware', 'HDD self-test detected imminent failure. Back up now.', 'Failing HDD, bad sectors, overheating, physical damage, power surges.', '1. BACK UP DATA NOW. 2. CrystalDiskInfo. 3. chkdsk /f /r. 4. Replace drive. 5. Clone to SSD.', 'critical'),
('FAN_FAILURE', 'System Fan Failure', 'hardware', 'System fan stopped spinning or not detected.', 'Fan motor failure, dust, loose connector, controller failure.', '1. Visually check fans. 2. Clean dust. 3. Check connectors. 4. Test fan directly. 5. Replace fan.', 'high'),
('USB_PORT_OVERCURRENT', 'USB Port Overcurrent', 'hardware', 'USB device drawing too much power. Overcurrent triggered.', 'Faulty device, damaged cable, port damage, PSU issue.', '1. Disconnect all USB. 2. Reboot. 3. Test one at a time. 4. Different port. 5. Replace device.', 'medium'),
('MEMORY_MANAGEMENT_ERROR', 'Memory Management Error', 'hardware', 'Windows detected memory management problem. Possible RAM failure.', 'Failing RAM, overheating RAM, incompatible RAM, overclocking.', '1. Windows Memory Diagnostic. 2. MemTest86. 3. Test sticks individually. 4. Reset overclock. 5. Reseat RAM.', 'high'),
('NO_BOOT_DEVICE', 'No Boot Device Found', 'hardware', 'BIOS cannot find a bootable device.', 'HDD disconnected, failed SSD, wrong boot order, loose cable, corrupt boot.', '1. Check BIOS boot order. 2. Check if drive detected. 3. Reseat cables. 4. Different port. 5. Replace drive.', 'critical'),
('E3', 'Printer Error E3 Paper Jam', 'printer', 'Printer detected paper jam or feed error.', 'Paper jam, worn roller, wrong paper type, tray misaligned.', '1. Unplug printer. 2. Remove jammed paper. 3. Check for torn pieces. 4. Clean roller. 5. Align paper.', 'low'),
('E1', 'Printer Error E1 Paper Out', 'printer', 'Paper tray empty or not detected.', 'Tray empty, paper loaded wrong, sensor dirty, wrong size setting.', '1. Refill tray. 2. Fan paper before loading. 3. Match guides to size. 4. Clean sensor. 5. Check size setting.', 'low'),
('WASTE_INK_PAD', 'Waste Ink Pad Full (Epson)', 'printer', 'Epson waste ink pad saturated. Printer stops printing.', 'Normal wear, excessive cleaning, heavy volume.', '1. Reset counter with adjustment program. 2. Replace ink pad. 3. External tube redirect. 4. Contact Epson service.', 'high'),
('DRUM_ERROR', 'Drum Unit Error (Brother)', 'printer', 'Brother laser printer drum needs replacement or cleaning.', 'Drum life exhausted, dirty surface, incompatible unit.', '1. Remove drum and toner. 2. Slide green tab 5-6 times. 3. Reinstall. 4. Replace if persists. 5. Reset counter.', 'medium'),
('CODE_43', 'Device Error Code 43', 'driver', 'Windows stopped a device due to reported problems.', 'Faulty GPU, loose power, overheating, driver corruption.', '1. Uninstall and restart. 2. Fresh driver. 3. Check power connectors. 4. Different PCIe slot. 5. Test elsewhere.', 'high'),
('CODE_10', 'Device Error Code 10 Cannot Start', 'driver', 'Device cannot start. Driver corrupted or missing.', 'Corrupted driver, incompatible, hardware failure, resource conflict.', '1. Uninstall with delete. 2. Scan hardware changes. 3. Manufacturer driver. 4. Try generic driver. 5. Check compatibility.', 'high'),
('CODE_41', 'Device Error Code 41', 'driver', 'Driver loaded but hardware not detected.', 'Loose connection, hardware failure, wrong driver, BIOS issue.', '1. Reseat hardware. 2. Update BIOS. 3. Reinstall driver. 4. Check BIOS detection. 5. Different slot.', 'high');
